  const compactMarketCap = v => {const n=Number(v);if(v==null||!Number.isFinite(n))return '—';return n>=1e12?`${(n/1e12).toFixed(2)}万亿`:n>=1e8?`${(n/1e8).toFixed(2)}亿`:n>=1e4?`${(n/1e4).toFixed(2)}万`:n.toFixed(0);};
